#include <LiquidCrystal.h>

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

void setup() {
  lcd.begin(16, 2);
  Serial.begin(9600);
  lcd.print("Ready...");
}

void loop() {
  if (Serial.available() > 0) {
    char c = Serial.read();
    if (c == '#') {
      lcd.clear();
    } else {
      lcd.print(c);
    }
  }
}
